import React from "react";
import { AbsoluteFill, useCurrentFrame } from "remotion";
import { Aroll, BK, Cta, END, EndCard, Flash, IEQ2_FPS, IEQ2_FRAMES, Lettering, Line, LogoBug, QuadWipe, SPLITS, Split } from "./IeqConvite2a";
import { M1, M2, M3, M4, M5, M6 } from "./IeqConvite2b";
import { M11, M12, M13, M14, M78, M910 } from "./IeqConvite2c";

// IGREJA DO EVANGELHO QUADRANGULAR (São João del-Rei), cliente do Leonardo — convite v3 (26/10): igual à v2, sem o botão
// de CTA dos primeiros 15 s (o diretor: "tire o cta do começo"); o botão continua no "clique no link" e no cartão final.
// A música nova (Broken Vessels) entra na mixagem (edit/tools/audio3.py).
// v2:
// o diretor: "mais motion no começo e ao longo do vídeo, intercalando motion com vídeo de forma natural".
// Metade do tempo é cena desenhada (IeqConvite2b/2c), a outra metade os pastores falando, trocando a cada 2–5 s.
// Base comum em IeqConvite2a. A v1 continua em IeqConvite.tsx.
export { IEQ2_FPS as IEQ3_FPS, IEQ2_FRAMES as IEQ3_FRAMES };

// lettering só nos trechos em que os pastores aparecem
const LETTERS: { a: number; b: number; lines: Line[] }[] = [
  { a: 2.43, b: 6.15, lines: [{ at: 2.45, text: "Tem algo na sua", kind: "kick" }, { at: 3.42, text: "Vida", kind: "block", size: 120 }, { at: 4.6, text: "ou na sua família", kind: "white", size: 76 }] },
  { a: 7.95, b: 9.56, lines: [{ at: 7.99, text: "Talvez uma situação", kind: "kick", size: 44 }] },
  { a: 13.37, b: 15.4, lines: [{ at: 13.4, text: "Ou um desejo de", kind: "kick" }] },
  { a: 15.42, b: 16.98, lines: [{ at: 15.44, text: "Se reaproximar", kind: "white", size: 84 }, { at: 16.3, text: "de Deus", kind: "block", size: 110 }] },
  { a: 17.28, b: 18.1, lines: [{ at: 17.3, text: "Então...", kind: "kick", size: 46 }] },
  { a: 20.82, b: 24.4, lines: [{ at: 20.84, text: "Você não precisa enfrentar", kind: "kick", size: 36 }, { at: 22.6, text: "Tudo", kind: "white", size: 100 }, { at: 23.3, text: "Sozinho", kind: "block", size: 124 }] },
  { a: 26.76, b: 28.78, lines: [{ at: 26.78, text: "Nós acreditamos em", kind: "kick" }, { at: 27.95, text: "Uma igreja", kind: "block", size: 112 }] },
  { a: 31.4, b: 33.55, lines: [{ at: 31.42, text: "Famílias caminham", kind: "kick" }, { at: 32.6, text: "Juntas", kind: "block", size: 120 }] },
  { a: 33.6, b: 34.85, lines: [{ at: 33.63, text: "E ninguém precisa ser", kind: "kick" }] },
  { a: 44.22, b: 46.42, lines: [{ at: 44.24, text: "Onde nós oramos por", kind: "kick" }, { at: 45.4, text: "Vidas", kind: "block", size: 120 }] },
  { a: 46.46, b: 47.8, lines: [{ at: 46.48, text: "Famílias", kind: "white", size: 96 }, { at: 47.1, text: "e cremos na", kind: "kick" }] },
  { a: 54.95, b: 57.3, lines: [{ at: 54.97, text: "Queremos construir uma", kind: "kick", size: 36 }, { at: 56.15, text: "Comunidade", kind: "block", size: 110 }] },
  { a: 60.34, b: 62.2, lines: [{ at: 60.36, text: "Pessoas que desejam", kind: "kick" }] },
  { a: 63.5, b: 66.4, lines: [{ at: 63.52, text: "Um lugar para", kind: "kick" }, { at: 65.35, text: "Pertencer", kind: "yel", size: 124 }] },
  { a: 69.95, b: 72.85, lines: [{ at: 69.97, text: "Um lugar para você", kind: "white", size: 72 }, { at: 71.3, text: "e sua família", kind: "block", size: 104 }] },
  { a: 72.9, b: 75.5, lines: [{ at: 72.92, text: "Crescerem", kind: "yel", size: 104 }, { at: 74.2, text: "e caminharem com Deus", kind: "white", size: 64 }] },
  { a: 80.98, b: END, lines: [{ at: 81.0, text: "Preparados para receber", kind: "kick", size: 36 }, { at: 82.8, text: "Você", kind: "block", size: 120 }, { at: 84.12, text: "e sua família", kind: "white", size: 76 }] },
];

export const IeqConvite3: React.FC = () => {
  const t = useCurrentFrame() / IEQ2_FPS;
  return (
    <AbsoluteFill style={{ background: BK }}>
      <Aroll t={t} />
      {SPLITS.map(([a, b, src]) => (
        <Split key={src} t={t} a={a} b={b} src={src} />
      ))}
      {LETTERS.map((L, i) => (
        <Lettering key={i} t={t} a={L.a} b={L.b} lines={L.lines} semBotao />
      ))}
      <LogoBug t={t} />
      <M1 t={t} />
      <M2 t={t} />
      <M3 t={t} />
      <M4 t={t} />
      <M5 t={t} />
      <M6 t={t} />
      <M78 t={t} />
      <M910 t={t} />
      <M11 t={t} />
      <M12 t={t} />
      <M13 t={t} />
      <M14 t={t} />
      <Cta t={t} inicio={false} />
      <QuadWipe t={t} at={7.8667} />
      <QuadWipe t={t} at={47.8} />
      <Flash t={t} at={15.42} o={0.7} />
      <Flash t={t} at={26.72} o={0.9} />
      <Flash t={t} at={75.6} o={0.6} />
      <EndCard t={t} />
    </AbsoluteFill>
  );
};

import { loadFont as loadSans } from "@remotion/google-fonts/Montserrat";
import { loadFont as loadCond } from "@remotion/google-fonts/SairaCondensed";
import React from "react";
import { AbsoluteFill, Easing, Img, OffthreadVideo, Sequence, interpolate, staticFile } from "remotion";

// IGREJA DO EVANGELHO QUADRANGULAR (São João del-Rei), cliente do Leonardo — convite, v2 (26/10). Base comum:
// cores, letras, vídeo dos pastores, tela dividida, lettering, cena desenhada, botão de CTA. As cenas ficam em IeqConvite2b.
// Pedido na v2: "mais motion no começo e ao longo do vídeo, intercalando motion com vídeo de forma natural".

const { fontFamily: F } = loadSans("normal", { weights: ["600", "700", "800", "900"], subsets: ["latin", "latin-ext"] });
const { fontFamily: C } = loadCond("normal", { weights: ["700", "800", "900"], subsets: ["latin", "latin-ext"] });
export { C, F };

export const IEQ2_FPS = 30;
export const IEQ2_FRAMES = Math.round(89.0 * IEQ2_FPS);
export const RED = "#D3262E";
export const YEL = "#F2B90F";
export const BLUE = "#1C7FC4";
export const PUR = "#6C2C93";
export const GREY = "#6B6B6E";
export const BK = "#0C0D10";
export const DARK = "#16171B";
export const LIGHT = "#F3F3F1";
export const QUAD = [RED, YEL, BLUE, PUR];
export const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
export const OUT = Easing.bezier(0.16, 1, 0.3, 1);
export const SOFT = Easing.bezier(0.2, 0.9, 0.3, 1);
export const INOUT = Easing.bezier(0.65, 0, 0.35, 1);
export const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
export const ease = (t: number, a: number, d = 0.4) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const SHADOW = "0 4px 22px rgba(0,0,0,0.75), 0 0 4px rgba(0,0,0,0.5)";
export const img = (f: string) => staticFile(`leonardo-ieq/${f}`);

// cortes da fala (edit/cortes.json)
const CUTS = [0, 7.8667, 13.2333, 17.1667, 24.8333, 36.6, 51.6667, 66.6333, 75.6];
export const END = 84.8;
const FRAMING: [number, string][] = [
  [1.1, "50% 62%"],
  [1.16, "50% 62%"],
  [1.1, "50% 60%"],
  [1.14, "50% 62%"],
  [1.2, "50% 62%"],
  [1.12, "50% 62%"],
  [1.22, "50% 60%"],
  [1.14, "50% 62%"],
  [1.2, "50% 62%"],
];
const PUNCH = [3.42, 23.3, 27.95, 32.6, 45.4, 56.15, 65.35, 71.3, 75.75, 82.8];

// cenas desenhadas (tela inteira) e telas divididas
export const MS: [number, number][] = [
  [0, 2.42],
  [6.18, 7.87],
  [9.58, 13.35],
  [18.1, 20.75],
  [24.9, 26.72],
  [28.8, 31.35],
  [34.85, 44.15],
  [47.8, 54.9],
  [57.35, 60.3],
  [62.2, 63.48],
  [66.63, 69.85],
  [78.08, 80.95],
];
export const inM = (t: number) => MS.some(([a, b]) => t >= a && t < b);
export const SPLITS: [number, number, string][] = [
  [13.35, 16.98, "b-louvor.mp4"],
  [31.35, 33.55, "b-familias.mp4"],
  [44.15, 46.42, "b-culto.mp4"],
  [69.9, 72.85, "b-sorrisos.mp4"],
  [72.85, 75.55, "b-criancas.mp4"],
];
const DARKS: [number, number][] = [[7.87, 9.58], [46.42, 47.8]];

const segAt = (t: number) => {
  let i = 0;
  for (let k = 0; k < CUTS.length; k++) if (CUTS[k] <= t + 1e-4) i = k;
  return i;
};
export const splitAmt = (t: number) => {
  let s = 0;
  for (const [a, b] of SPLITS) if (t >= a - 0.01 && t < b + 0.35) s = Math.max(s, Math.min(ease(t, a, 0.38), 1 - ease(t, b, 0.35)));
  if (t >= 72.85 && t < 72.9) s = 1;
  return s;
};
const darkAmt = (t: number) => {
  let d = 0;
  for (const [a, b] of DARKS) if (t >= a && t < b + 0.5) d = Math.max(d, Math.min(lin(t, a, a + 0.3), 1 - lin(t, b, b + 0.45)));
  return d;
};

export const Aroll: React.FC<{ t: number }> = ({ t }) => {
  const i = segAt(t);
  const [z0, origin] = FRAMING[i];
  let z = z0 + 0.04 * lin(t, CUTS[i], (CUTS[i + 1] ?? END) - 0.01);
  for (const p of PUNCH) if (t >= p && t < p + 0.55) z += 0.07 * interpolate(t, [p, p + 0.08, p + 0.55], [0, 1, 0.45], cl);
  // ao sair de uma cena desenhada, a imagem chega com uma aproximação curta
  for (const [, b] of MS) if (t >= b && t < b + 0.5) z += 0.1 * (1 - ease(t, b, 0.5));
  const sp = splitAmt(t);
  const d = darkAmt(t);
  return (
    <AbsoluteFill style={{ background: BK, overflow: "hidden" }}>
      <OffthreadVideo
        src={img("aroll.mp4")}
        muted
        style={{
          position: "absolute",
          inset: 0,
          width: "100%",
          height: "100%",
          objectFit: "cover",
          transform: `translateY(${(-280 * sp).toFixed(1)}px) scale(${(z - 0.06 * sp).toFixed(4)})`,
          transformOrigin: origin,
          filter: d > 0 ? `grayscale(${(0.85 * d).toFixed(3)}) brightness(${(1 - 0.28 * d).toFixed(3)}) contrast(${(1 + 0.18 * d).toFixed(3)})` : undefined,
        }}
      />
      <AbsoluteFill style={{ background: "radial-gradient(ellipse 75% 60% at 50% 42%, rgba(0,0,0,0) 40%, rgba(0,0,0,0.85) 100%)", opacity: d }} />
      <AbsoluteFill style={{ background: "linear-gradient(180deg, rgba(0,0,0,0.35) 0%, rgba(0,0,0,0) 15%, rgba(0,0,0,0) 44%, rgba(0,0,0,0.5) 70%, rgba(0,0,0,0.78) 100%)" }} />
    </AbsoluteFill>
  );
};

export const QuadBar: React.FC<{ w: number; h?: number; p?: number }> = ({ w, h = 10, p = 1 }) => (
  <div style={{ display: "flex", width: w, height: h }}>
    {QUAD.map((c, i) => (
      <div key={i} style={{ flex: 1, background: c, transform: `scaleX(${Math.max(0, Math.min(1, p * 4 - i)).toFixed(3)})`, transformOrigin: "0% 50%" }} />
    ))}
  </div>
);

const PANEL_TOP = 1020;
export const Split: React.FC<{ t: number; a: number; b: number; src: string }> = ({ t, a, b, src }) => {
  if (t < a || t >= b + 0.35) return null;
  const chained = SPLITS.some(([a2]) => Math.abs(a2 - b) < 0.02);
  const prev = SPLITS.some(([, b2]) => Math.abs(b2 - a) < 0.02);
  if (chained && t >= b) return null;
  const e = prev ? 1 : ease(t, a, 0.38);
  const x = chained ? 0 : ease(t, b, 0.35);
  const y = (1 - e + x) * 920;
  const cam = 1.04 + 0.08 * lin(t, a, b);
  const cross = prev ? lin(t, a, a + 0.3) : 1;
  return (
    <div style={{ position: "absolute", left: 0, top: PANEL_TOP, width: 1080, height: 900, overflow: "hidden", transform: `translateY(${y.toFixed(1)}px)` }}>
      <div style={{ position: "absolute", inset: 0, background: BK, clipPath: prev ? `inset(0 ${((1 - cross) * 100).toFixed(1)}% 0 0)` : undefined }}>
        <div style={{ position: "absolute", inset: 0, transform: `scale(${cam.toFixed(4)})` }}>
          <Sequence from={Math.round(a * IEQ2_FPS)} layout="none">
            <OffthreadVideo src={img(src)} muted style={{ position: "absolute", inset: 0, width: "100%", height: "100%", objectFit: "cover" }} />
          </Sequence>
        </div>
        <div style={{ position: "absolute", inset: 0, background: "linear-gradient(180deg, rgba(0,0,0,0.55) 0%, rgba(0,0,0,0) 30%, rgba(0,0,0,0) 70%, rgba(0,0,0,0.45) 100%)" }} />
      </div>
      <div style={{ position: "absolute", left: 0, top: 0 }}>
        <QuadBar w={1080} h={12} />
      </div>
    </div>
  );
};

export const QuadWipe: React.FC<{ t: number; at: number }> = ({ t, at }) => {
  const d = 0.26;
  if (t < at - d - 0.1 || t > at + d + 0.1) return null;
  return (
    <AbsoluteFill>
      {QUAD.map((c, i) => {
        const p = lin(t, at - d + (i - 1.5) * 0.04, at + d + (i - 1.5) * 0.04);
        return <div key={i} style={{ position: "absolute", left: i * 270, top: 0, width: 271, height: 1920, background: c, transform: `translateY(${((1 - p * 2) * 2000).toFixed(0)}px)` }} />;
      })}
    </AbsoluteFill>
  );
};
export const Flash: React.FC<{ t: number; at: number; o?: number }> = ({ t, at, o = 0.85 }) => {
  if (t < at - 0.04 || t > at + 0.3) return null;
  const v = t < at ? lin(t, at - 0.04, at) : 1 - lin(t, at, at + 0.3);
  return <AbsoluteFill style={{ background: "#FFFFFF", opacity: v * o }} />;
};

// lettering (sobre os pastores)
type Kind = "kick" | "block" | "white" | "dark" | "kickDark" | "yel" | "blue" | "pur";
export type Line = { at: number; text: string; kind: Kind; size?: number };
export const LineEl: React.FC<{ t: number; l: Line }> = ({ t, l }) => {
  const e = ease(t, l.at, 0.3);
  const vis = t >= l.at ? 1 : 0;
  if (l.kind === "kick" || l.kind === "kickDark")
    return (
      <div style={{ fontFamily: F, fontWeight: 800, fontSize: l.size ?? 40, letterSpacing: "0.14em", color: l.kind === "kick" ? "#FFFFFF" : BK, textTransform: "uppercase", whiteSpace: "nowrap", textShadow: l.kind === "kick" ? SHADOW : "none", opacity: e * vis, transform: `translateY(${((1 - e) * 24).toFixed(1)}px)` }}>
        {l.text}
      </div>
    );
  const s = interpolate(t, [l.at, l.at + 0.2], [1.6, 1], { ...cl, easing: OUT });
  const bg = { block: RED, dark: BK, white: "#FFFFFF", yel: YEL, blue: BLUE, pur: PUR }[l.kind];
  const fg = l.kind === "white" || l.kind === "yel" ? BK : "#FFFFFF";
  return (
    <div style={{ fontFamily: C, fontWeight: 900, fontSize: l.size ?? 104, lineHeight: 1, color: fg, background: bg, padding: "8px 30px 12px", borderRadius: 8, textTransform: "uppercase", whiteSpace: "nowrap", boxShadow: "0 14px 34px rgba(0,0,0,0.42)", opacity: vis * Math.min(1, e * 3), transform: `scale(${s.toFixed(4)})` }}>
      {l.text}
    </div>
  );
};
export const Lettering: React.FC<{ t: number; a: number; b: number; lines: Line[]; semBotao?: boolean }> = ({ t, a, b, lines, semBotao }) => {
  if (t < a || t >= b) return null;
  const out = 1 - lin(t, b - 0.14, b);
  const inSplit = SPLITS.some(([sa, sb]) => a >= sa - 0.05 && a < sb);
  const y = inSplit ? 870 : a < 15 && !semBotao ? 1010 : 1090;
  return (
    <div style={{ position: "absolute", left: 120, right: 120, top: y, display: "flex", flexDirection: "column", alignItems: "center", gap: 14, opacity: out }}>
      {lines.map((l, i) => (
        <LineEl key={i} t={t} l={l} />
      ))}
      {!inSplit ? (
        <div style={{ marginTop: 6 }}>
          <QuadBar w={260} h={8} p={ease(t, a, 0.5)} />
        </div>
      ) : null}
    </div>
  );
};

// cena desenhada: entra e sai com transições variadas, câmera sempre andando
export type Tin = "none" | "square" | "slide" | "doorsV" | "doorsH" | "zoom" | "drop" | "rise" | "iris" | "push";
export type Tout = "none" | "zoomThru" | "up" | "left" | "right" | "down" | "flash";
const inStyle = (k: Tin, e: number): React.CSSProperties => {
  if (k === "none") return {};
  if (k === "square") {
    const s = ((1 - e) * 50).toFixed(2);
    return { clipPath: `inset(${s}% ${s}% ${s}% ${s}%)` };
  }
  if (k === "slide") return { transform: `translateX(${((1 - e) * -1080).toFixed(0)}px)` };
  if (k === "push") return { transform: `translateX(${((1 - e) * 1080).toFixed(0)}px)`, boxShadow: "-30px 0 80px rgba(0,0,0,0.5)" };
  if (k === "doorsV") return { clipPath: `inset(0% ${((1 - e) * 50).toFixed(2)}% 0% ${((1 - e) * 50).toFixed(2)}%)` };
  if (k === "doorsH") return { clipPath: `inset(${((1 - e) * 50).toFixed(2)}% 0% ${((1 - e) * 50).toFixed(2)}% 0%)` };
  if (k === "drop") return { transform: `translateY(${((1 - e) * -1920).toFixed(0)}px)` };
  if (k === "rise") return { transform: `translateY(${((1 - e) * 1920).toFixed(0)}px)` };
  if (k === "iris") return { clipPath: `circle(${(e * 120).toFixed(1)}% at 50% 38%)` };
  return { opacity: Math.min(1, e * 2), transform: `scale(${(1.8 - 0.8 * e).toFixed(4)})` };
};
const outStyle = (k: Tout, x: number): React.CSSProperties => {
  if (x <= 0 || k === "none" || k === "flash") return {};
  if (k === "zoomThru") return { transform: `scale(${(1 + 1.6 * x).toFixed(4)})`, opacity: 1 - x };
  if (k === "up") return { transform: `translateY(${(-x * 1920).toFixed(0)}px)` };
  if (k === "down") return { transform: `translateY(${(x * 1920).toFixed(0)}px)` };
  if (k === "left") return { transform: `translateX(${(-x * 1080).toFixed(0)}px)` };
  return { transform: `translateX(${(x * 1080).toFixed(0)}px)` };
};
export const Scene: React.FC<{ t: number; a: number; b: number; bg: string; tin: Tin; tout: Tout; cam?: [number, number, number, number]; children: React.ReactNode }> = ({ t, a, b, bg, tin, tout, cam = [0.94, 1.06, 0, 0], children }) => {
  if (t < a || t >= b) return null;
  const e = INOUT(lin(t, a, a + 0.32));
  const x = Easing.in(Easing.quad)(lin(t, b - 0.26, b));
  const p = interpolate(t, [a, b], [0, 1], { ...cl, easing: Easing.out(Easing.quad) });
  const [z0, z1, dx, dy] = cam;
  return (
    <AbsoluteFill style={outStyle(tout, x)}>
      <AbsoluteFill style={{ background: bg, overflow: "hidden", ...inStyle(tin, e) }}>
        <AbsoluteFill style={{ transform: `translate(${(dx * p).toFixed(1)}px, ${(dy * p).toFixed(1)}px) scale(${(z0 + (z1 - z0) * p).toFixed(4)})`, transformOrigin: "50% 45%" }}>{children}</AbsoluteFill>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};
export const Big: React.FC<{ t: number; at: number; size: number; color: string; bg?: string; cond?: boolean; spacing?: string; children: string }> = ({ t, at, size, color, bg, cond = true, spacing = "0.01em", children }) => {
  const e = interpolate(t, [at, at + 0.22], [0, 1], { ...cl, easing: OUT });
  return (
    <div style={{ fontFamily: cond ? C : F, fontWeight: cond ? 900 : 800, fontSize: size, lineHeight: 1, letterSpacing: spacing, color, background: bg, padding: bg ? `${size * 0.08}px ${size * 0.26}px ${size * 0.12}px` : undefined, borderRadius: bg ? size * 0.1 : undefined, textTransform: "uppercase", whiteSpace: "nowrap", opacity: t >= at ? Math.min(1, e * 3) : 0, transform: `scale(${(1.6 - 0.6 * e).toFixed(4)})` }}>
      {children}
    </div>
  );
};
export const Pop: React.FC<{ t: number; at: number; d?: number; children: React.ReactNode }> = ({ t, at, d = 0.4, children }) => {
  const p = interpolate(t, [at, at + d], [0, 1], { ...cl, easing: SOFT });
  return <div style={{ opacity: t >= at ? Math.min(1, p * 2) : 0, transform: `scale(${(0.4 + 0.6 * p).toFixed(4)})` }}>{children}</div>;
};
export const Col: React.FC<{ top: number; gap?: number; children: React.ReactNode }> = ({ top, gap = 22, children }) => (
  <div style={{ position: "absolute", left: 110, right: 110, top, display: "flex", flexDirection: "column", alignItems: "center", gap }}>{children}</div>
);
// traço que se desenha (pathLength = 1)
export const Draw: React.FC<{ d: string; p: number; stroke: string; w?: number; fill?: string }> = ({ d, p, stroke, w = 3, fill = "none" }) => (
  <path d={d} pathLength={1} fill={fill} stroke={stroke} strokeWidth={w} strokeLinecap="round" strokeLinejoin="round" strokeDasharray={1} strokeDashoffset={(1 - Math.max(0, Math.min(1, p))).toFixed(4)} />
);
export const SymTile: React.FC<{ s: number }> = ({ s }) => (
