// o símbolo se monta: os 4 quadrantes chegam dos cantos
export const SymbolBuild: React.FC<{ t: number; at: number; s: number; d?: number }> = ({ t, at, s, d = 0.45 }) => {
  const half = s / 2;
  const hh = half * (310 / 318);
  const from: [number, number][] = [[-700, -700], [700, -700], [-700, 700], [700, 700]];
  return (
    <div style={{ position: "relative", width: s, height: hh * 2 }}>
      {[0, 1, 2, 3].map((i) => {
        const e = interpolate(t, [at + i * 0.07, at + i * 0.07 + d], [0, 1], { ...cl, easing: OUT });
        const [fx, fy] = from[i];
        return (
          <Img
            key={i}
            src={img(`q${i}.png`)}
            style={{ position: "absolute", left: (i % 2) * half, top: Math.floor(i / 2) * hh, width: half, height: hh, opacity: Math.min(1, e * 3), transform: `translate(${((1 - e) * fx).toFixed(1)}px, ${((1 - e) * fy).toFixed(1)}px) rotate(${((1 - e) * (i % 2 ? 40 : -40)).toFixed(1)}deg)` }}
          />
        );
      })}
    </div>
  );
};

