export const Button: React.FC<{ t: number; t0: number; e: number; scale: number; top: string; bottom: string }> = ({ t, t0, e, scale, top, bottom }) => {
  const beat = (t - t0) % 1.0;
  const pulse = 1 + 0.06 * Math.sin(Math.PI * Math.min(1, beat / 0.45)) * (beat < 0.45 ? 1 : 0);
  return (
    <div style={{ position: "relative", transform: `scale(${(scale * e * pulse).toFixed(4)})`, transformOrigin: "50% 0%" }}>
      <div style={{ position: "absolute", inset: 0, borderRadius: 999, border: `5px solid ${YEL}`, transform: `scale(${(1 + beat * 0.16).toFixed(3)}, ${(1 + beat * 0.5).toFixed(3)})`, opacity: (1 - beat) * 0.85 }} />
