};
const CTA_A = 0.8;
const CTA_B = 15.0;
export const Cta: React.FC<{ t: number; inicio?: boolean }> = ({ t, inicio = true }) => {
  // v3 (o diretor: "tire o cta do começo"): inicio=false some com o botão dos primeiros 15 s
  if (inicio && t >= CTA_A && t < CTA_B) {
    // some no trecho do problema e na tela dividida; nas cenas da abertura fica embaixo
    if ((t >= 9.58 && t < 13.35) || splitAmt(t) > 0) return null;
    const on = interpolate(t, [CTA_A, CTA_A + 0.45], [0, 1], { ...cl, easing: SOFT });
    const re = t >= 7.87 && t < 8.3 ? interpolate(t, [7.87, 8.25], [0.6, 1], { ...cl, easing: SOFT }) : 1;
    const off = 1 - lin(t, CTA_B - 0.25, CTA_B);
    return (
      <div style={{ position: "absolute", left: 0, right: 0, top: 1360, display: "flex", justifyContent: "center", opacity: off }}>
        <Button t={t} t0={CTA_A} e={Math.min(on, re)} scale={0.8} top="Queremos te acolher" bottom="Clica aqui agora" />
      </div>
    );
  }
  if (t >= 75.7 && t < 78.08) {
    const on = interpolate(t, [75.72, 76.1], [0, 1], { ...cl, easing: SOFT });
    return (
      <div style={{ position: "absolute", left: 0, right: 0, top: 1040, display: "flex", flexDirection: "column", alignItems: "center", gap: 30 }}>
        <LineEl t={t} l={{ at: 75.74, text: "Clique no link", kind: "block", size: 112 }} />
        <Button t={t} t0={75.72} e={on} scale={0.95} top="Fale com a gente" bottom="Clica aqui agora" />
      </div>
    );
  }
  return null;
};

