// Quadrangular v2 — cenas desenhadas 7 a 14 (multidão, "um lugar para", restauração/cura/libertação, lares,
// famílias/casais/jovens/adultos, recomeçar, lupa, conversa no celular).

const Person: React.FC<{ x: number; y: number; s: number; c: string }> = ({ x, y, s, c }) => (
  <g transform={`translate(${x} ${y}) scale(${s})`}>
    <circle cx={0} cy={-18} r={13} fill={c} />
    <path d="M-24 22 C-24 2 -12 -4 0 -4 C12 -4 24 2 24 22 Z" fill={c} />
  </g>
);
// 7 · "apenas mais um": na multidão, uma pessoa acende
const Grid: React.FC<{ t: number }> = ({ t }) => {
  const hi = ease(t, 35.05, 0.45);
  const cols = 6;
  return (
    <svg width={1080} height={860} viewBox="0 0 1080 860" style={{ position: "absolute", left: 0, top: 220 }}>
      {Array.from({ length: 30 }).map((_, k) => {
        const i = k % cols;
        const j = Math.floor(k / cols);
        const special = i === 2 && j === 2;
        const e = ease(t, 34.88 + (i + j) * 0.03, 0.3);
        return <Person key={k} x={115 + i * 170} y={110 + j * 160 + (1 - e) * 60} s={(special ? 2.1 + 1.2 * hi : 2.1) * e} c={special && hi > 0.3 ? YEL : "#3A3B40"} />;
      })}
